// Self-checking testbench for first_counter.v
// DUT is instantiated in tb, tb will contain a clock generator, reset
// generator, enable logic generator, compare logic.


// step1: create a dummy template that declares inputs to DUT as reg,
// declare outputs of DUT as wire. Note there is no port list for test
// bench.
module first_counter_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;

reg clk, reset, enable;
reg instrument_clk;
wire[3:0] counter_out;
wire overflow_out;


first_counter U0(
    .clk (clk),
    .reset (reset),
    .enable (enable),
    .counter_out (counter_out),
    .overflow_out (overflow_out)
);

// step2: add clock generator logic. Before this we need to drive all
// inputs of DUT to some known state.
initial begin
    //wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB
 // initial block only executes once 
    clk = 0;
    instrument_clk = 0;
    reset = 0;
    enable = 0;
end

always
    #5 clk = !clk;

always
    #5 instrument_clk = !instrument_clk; // IMPORTANT: Make sure that this reflects the granularity of the oracle w.r.t. the clock cycle!


integer f;
initial begin
    f = $fopen("output.txt");
    $display("\t\ttime,\tclk,\treset,\tenable,\tcount_out,\toverflow_out\n");
    $fwrite(f, "time,counter_out[3],counter_out[2],counter_out[1],counter_out[0],overflow_out\n");
    $monitor("%d, \t%b, \t%b, \t%b, \t%d, \t\t%b", $time, clk, reset, enable, counter_out, overflow_out);
    forever begin
    //@(posedge instrument_clk);
    //#5
    #1
    $fwrite(f, "%0d,%b,%b,%b,%b,%b\n", $time, counter_out[3], counter_out[2], counter_out[1], counter_out[0], overflow_out);
    end
end



event reset_trigger;
event reset_done_trigger;
event terminate_sim;


initial begin
    #5
    forever begin
        @(reset_trigger);
        @(negedge clk);
        reset = 1;
        @(negedge clk);
        reset = 0;
        -> reset_done_trigger;
    end
end

initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    @(terminate_sim);
    #5
    $fclose(f);
    $finish;
end

/*
// Test Case 1: Assert/Deassert reset
// trigger the reset_trigger event after 10 time units
initial begin: TEST_CASE_1
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    #10 -> reset_trigger;
end
*/



// Test Case 2: Assert/Deassert enable after reset is applied
// trigger the reset logic and wait for it to complete. Then drive
// enable to 1
/*
reg temp_event1;

initial begin
    temp_event1 = 0;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

       #10;
    temp_event1 = 1;
end
*/
/*
initial begin: TEST_CASE_2
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    #10 -> reset_trigger;
   // @(posedge temp_event1);

    @(reset_done_trigger);
    @(negedge clk);
    enable = 1;
    repeat (10) begin
        @(negedge clk);
    end
    enable = 0;
    #5 -> terminate_sim;
end
*/

initial begin: TEST_CASE_4
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    #10 -> reset_trigger;
   // @(posedge temp_event1);

    @(reset_done_trigger);
    @(negedge clk);
    enable = 1;
    repeat (100) begin
        @(negedge clk);
    end
    enable = 0;
    #5 -> terminate_sim;
end

initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    #253

    //@(negedge clk)
    //#5 $display ("Simulation SUCCESS!");
     -> terminate_sim; // terminate simulation after 100 time units.

end
initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

#2000000
$finish;
end



// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    // Synchronization with the test harness
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    // Initialize Inputs
    // We initialize clk to 0 to ensure the clock generator has a valid starting point
    // in case the original TB's initialization is delayed.
    clk = 0;
    reset = 0;
    enable = 0;

    // Wait for stabilization
    #10;

    // ---------------------------------------------------------
    // Test Case 1: Reset Priority & Initialization
    // ---------------------------------------------------------
    // Assert Reset and Enable simultaneously. 
    // This targets control flow mutations (e.g., swapping if/else priority).
    // If priority is swapped, counter might increment instead of reset.
    @(negedge clk);
    reset = 1;
    enable = 1;
    @(negedge clk);

    // Deassert Reset, verify counter starts at 0.
    // Enable is still 1, so counting should start in the next cycle.
    reset = 0;

    // ---------------------------------------------------------
    // Test Case 2: Full Count Range & Overflow Logic
    // ---------------------------------------------------------
    // Count from 0 to 15 and wrap around to 0.
    // This targets:
    // - Operator mutations (e.g., + to -)
    // - Constant mutations (e.g., changing 15 to 14)
    // - Bit-width mutations (e.g., counter_out[2:0])
    // - Overflow logic (verifying the sticky bit behavior at 15->0 transition)

    // We loop 20 times to ensure we pass the wrap-around point (16 cycles).
    for (i = 0; i < 20; i = i + 1) begin
        @(negedge clk);
    end

    // ---------------------------------------------------------
    // Test Case 3: Enable Control (Pause/Resume)
    // ---------------------------------------------------------
    // Deassert Enable. Counter should hold its value.
    // Targets enable signal sensitivity and logic deletion.
    enable = 0;
    for (i = 0; i < 5; i = i + 1) begin
        @(negedge clk);
    end

    // Resume counting to verify state retention and resumption.
    enable = 1;
    for (i = 0; i < 5; i = i + 1) begin
        @(negedge clk);
    end

    // ---------------------------------------------------------
    // Test Case 4: Reset Clearing Overflow
    // ---------------------------------------------------------
    // Assert reset in the middle of counting to ensure it clears 
    // both the counter and the sticky overflow bit.
    @(negedge clk);
    reset = 1;
    enable = 0;
    @(negedge clk);
    reset = 0;

    // ---------------------------------------------------------
    // Test Case 5: Rapid Control Signal Transitions
    // ---------------------------------------------------------
    // Rapidly toggle enable to stress transition logic and expose
    // potential edge-detection or sensitivity list faults.
    @(negedge clk);
    enable = 1;
    @(negedge clk);
    enable = 0;
    @(negedge clk);
    enable = 1;
    @(negedge clk);
    enable = 0;

    // 4. Cleanup / Handover
    #20;
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (f != 0) $fclose(f);
    $finish;
end

endmodule

